  "Dosya içeriği, izinler ve zaman damgaları SHA-256 manifestiyle korunur.": {"tr":"Dosya içeriği, izinler ve zaman damgaları SHA-256 manifestiyle korunur.","en":"File contents, permissions, and timestamps are preserved with a SHA-256 manifest."},
  "Agent seçilen yedekleme motorunu desteklemiyor. Agent yeteneklerini kontrol edin veya Agent’ı güncelleyin.": {"tr":"Yedekleme bilgisayarı seçilen yedekleme motorunu desteklemiyor. Yeteneklerini kontrol edin veya programını güncelleyin.","en":"The backup computer does not support the selected backup engine. Check its capabilities or update the backup computer."},
  "3-2-1 koruması": {"tr":"3-2-1 koruması","en":"3-2-1 protection"},
